import json,os
def transform(grid):
    h=len(grid); w=len(grid[0])
    out=[[0]*(w//3) for _ in range(h//3)]
    from collections import defaultdict
    B=defaultdict(list)
    for i,row in enumerate(grid):
        for j,x in enumerate(row):
            if x not in (0,5): B[(i//3,j//3)].append(x)
    for (bi,bj),v in B.items():
        if len(v)>=3 and len(set(v))==1: out[bi][bj]=v[0]
    return out
